## Federation Envelope

### Requirements

| ID | Requirement | Priority |
|----|-------------|----------|
| F1 | Messages include source system identifier | Must |
| F2 | Messages include target system identifier | Must |
| F3 | Hop count tracking for loop prevention | Must |
| F4 | Routing path tracking for debugging | Should |
| F5 | Correlation ID for cross-system tracing | Should |
| F6 | Message signing for integrity | Deferred |

### Type Definitions

```typescript
interface FederationMetadata {
  sourceSystem: string;
  targetSystem: string;
  hopCount: number;
  maxHops?: number;
  path?: string[];
  originTimestamp: Timestamp;
  correlationId?: string;
  signature?: string;  // TODO: Define signing later
}

interface FederationEnvelope<T = unknown> {
  payload: T;
  federation: FederationMetadata;
}

interface FederationRoutingConfig {
  systemId: string;
  maxHops?: number;
  trackPath?: boolean;
  allowedTargets?: string[];
  allowedSources?: string[];
}

// Updated request params
interface FederationRouteRequestParams {
  systemId: string;
  envelope: FederationEnvelope<Message>;
  /** @deprecated Use envelope instead */
  message?: Message;
  _meta?: Meta;
}

// New error codes
FEDERATION_LOOP_DETECTED: 5010,
FEDERATION_MAX_HOPS_EXCEEDED: 5011,
```

### Routing Logic

```typescript
function processFederationEnvelope<T>(
  envelope: FederationEnvelope<T>,
  config: FederationRoutingConfig
): FederationEnvelope<T> | null {
  const { federation } = envelope;
  const maxHops = federation.maxHops ?? config.maxHops ?? 10;

  // Check hop count
  if (federation.hopCount >= maxHops) return null;

  // Check for loops
  if (federation.path?.includes(config.systemId)) return null;

  // Check source allowlist
  if (config.allowedSources && !config.allowedSources.includes(federation.sourceSystem)) {
    return null;
  }

  // Update for forwarding
  return {
    payload: envelope.payload,
    federation: {
      ...federation,
      hopCount: federation.hopCount + 1,
      path: config.trackPath
        ? [...(federation.path ?? []), config.systemId]
        : undefined,
    },
  };
}

function createFederationEnvelope<T>(
  payload: T,
  sourceSystem: string,
  targetSystem: string,
  options?: { correlationId?: string; maxHops?: number; trackPath?: boolean }
): FederationEnvelope<T> {
  return {
    payload,
    federation: {
      sourceSystem,
      targetSystem,
      hopCount: 0,
      maxHops: options?.maxHops,
      path: options?.trackPath ? [sourceSystem] : undefined,
      originTimestamp: Date.now(),
      correlationId: options?.correlationId,
    },
  };
}
```

